"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["37873"],{28154(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_fada.base_legal_nao_encontrada","status":422,"titulo":"Base legal do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA) n\xe3o encontrada ou desativada"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_fada.base_legal_nao_encontrada","requisitos":[],"oQueAconteceu":["A declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (`aplica: true`) trouxe um\\n`baseLegal.id` que n\xe3o corresponde a nenhuma base legal ativa no cadastro de\\nbases legais do fator, mantido no m\xf3dulo Configura\xe7\xe3o. O identificador n\xe3o existe ou a base\\nlegal foi desativada; o sistema responde da mesma forma nos dois casos e n\xe3o diz qual deles\\nocorreu.","A base legal \xe9 o que traz o instrumento normativo e os munic\xedpios abrangidos pelo fator. A\\ndeclara\xe7\xe3o copia esses dados do cadastro no momento em que \xe9 gravada.","A confer\xeancia vem depois da regra\\n([`regra_nao_encontrada`](/erros/uniplus.selecao.configuracao_do_fada.regra_nao_encontrada)\\ne\\n[`regra_tipo_invalido`](/erros/uniplus.selecao.configuracao_do_fada.regra_tipo_invalido))\\ne antes dos valores do fator, do teto e do fato de elegibilidade. A primeira recusa\\ninterrompe a declara\xe7\xe3o e nada \xe9 gravado."],"comoResolver":["Confira, no cadastro de bases legais do Fator de Atenua\xe7\xe3o (Configura\xe7\xe3o), o identificador\\nda base legal que o edital cita e se ela continua ativa. Se n\xe3o houver base legal ativa para\\no edital, cadastre uma antes de declarar o fator. Em seguida, reenvie a declara\xe7\xe3o com o\\nidentificador correto.","Alterar depois a base legal no cadastro n\xe3o muda o que o processo j\xe1 declarou: para que o\\nprocesso passe a usar a altera\xe7\xe3o, \xe9 preciso declarar o fator de novo."],"ondeAparece":["Declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do fada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);